// === Tab: mySketch ===
let points = [];
let keyframes = [];
let currentFrame = 0;
let isEditing = true;
let maxFrames = 100;
let transitionFrames = 15; 
let transitionCounter = 0;
let isPlaying = false;
let interpolatedPoints = [];

function setup() {
  createCanvas(800, 600);
  let playButton = createButton('Play');
  playButton.position(10, height + 10);
  playButton.mousePressed(playAnimation);
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

  background(255);
  if (isEditing) {
    drawPoints(points);
    drawInstructions("make something, then press 'p' to go to keyframe mode. press it again to go back to edit mode.");
  } else {
    if (isPlaying) {
      if (currentFrame < maxFrames - 1) {
        if (transitionCounter < transitionFrames) {
          updateInterpolatedPoints();
          transitionCounter++;
        } else {
          currentFrame++;
          transitionCounter = 0;
          if (currentFrame < maxFrames - 1) {
            loadKeyframe(currentFrame);
          }
        }
        drawPoints(interpolatedPoints);
      } else {
        isPlaying = false;
      }
    } else {
      drawKeyframe();
    }
    drawInstructions("use left/right arrows to switch frames. drag joints to create keyframes.");
    drawFrameUI();
  }
}

function drawPoints(pts) {
  stroke(0);
  strokeWeight(4);
  noFill();
  beginShape();
  for (let point of pts) {
    vertex(point.x, point.y);
    ellipse(point.x, point.y, 10, 10);
  }
  endShape();
}

function drawInstructions(txt) {
  fill(0);
  noStroke();
  textSize(16);
  text(txt, 10, height - 30);
}

function mousePressed() {
  if (isEditing) {
    points.push(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
  } else {
    for (let point of points) {
      if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), point.x, point.y) < 10) {
        point.dragging = true;
      }
    }
  }
}

function mouseDragged() {
  if (!isEditing) {
    for (let point of points) {
      if (point.dragging) {
        point.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
        point.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
        saveKeyframe(currentFrame, points);
      }
    }
  }
}

function mouseReleased() {
  if (!isEditing) {
    for (let point of points) {
      point.dragging = false;
    }
  }
}

function keyPressed() {
  if (key === 'p' || key === 'P') {
    isEditing = !isEditing;
    if (!isEditing && keyframes.length === 0) {
      saveKeyframe(0, points);
    }
  } else if (!isEditing) {
    if (keyCode === LEFT_ARROW) {
      if (currentFrame > 0) {
        currentFrame--;
        transitionCounter = 0;
        loadKeyframe(currentFrame);
        updateInterpolatedPoints();
      }
    } else if (keyCode === RIGHT_ARROW) {
      if (currentFrame < maxFrames - 1) {
        currentFrame++;
        transitionCounter = 0;
        loadKeyframe(currentFrame);
        updateInterpolatedPoints();
      }
    }
  }
}

function saveKeyframe(frame, pts) {
  keyframes[frame] = pts.map(p => createVector(p.x, p.y));
}

function loadKeyframe(frame) {
  if (keyframes[frame]) {
    points = keyframes[frame].map(p => createVector(p.x, p.y));
  }
}

function updateInterpolatedPoints() {
  let startFrame = currentFrame;
  let endFrame = min(maxFrames - 1, currentFrame + 1);
  if (keyframes[startFrame] && keyframes[endFrame]) {
    let startPoints = keyframes[startFrame];
    let endPoints = keyframes[endFrame];
    let t = transitionCounter / transitionFrames;
    interpolatedPoints = startPoints.map((start, i) => p5.Vector.lerp(start, endPoints[i], t));
  } else {
    interpolatedPoints = points;
  }
}

function drawKeyframe() {
  if (keyframes[currentFrame]) {
    drawPoints(keyframes[currentFrame]);
  } else {
    drawPoints(points);
  }
}

function drawFrameUI() {
  let frameWidth = width / maxFrames;
  for (let i = 0; i < maxFrames; i++) {
    if (i === currentFrame) {
      fill(255, 0, 0);
    } else if (keyframes[i]) {
      fill(0, 0, 255);
    } else {
      fill(255);
    }
    rect(i * frameWidth, height - 20, frameWidth, 20);
  }
}

function playAnimation() {
  isPlaying = true;
  currentFrame = 0;
  transitionCounter = 0;
  if (keyframes[currentFrame]) {
    loadKeyframe(currentFrame);
    updateInterpolatedPoints();
  }
}

